        const scanFunction = ui.match(/async function scanBarcode\(barcode\) \{[\s\S]*?(?=\n    function captureVvpQuantity)/)?.[0];
        assert.ok(scanFunction,"Stock Inward scan controller can be exercised in isolation");
        async function simulateScan({ isVvp, capturedQuantity }) {
            const calls = []; let focusCount = 0; let modalCount = 0;
            const context = vm.createContext({
                documentData:{document:{id:77}}, active:true,saveContext:async()=>true,scannerHeaderIsValid:()=>true,duplicateClear:true,
                api:()=>({stockInwardResolveBarcode:async()=>({resolution:"UNIQUE",product:{variable_value:isVvp?1:0}}),stockInwardScan:async input=>{calls.push(input);return {lastResolution:"UNIQUE"};}}),
                captureVvpQuantity:async()=>{modalCount++;return capturedQuantity;},
                showMessage:()=>{},render:()=>{},el:id=>id==="siScanner"?{focus:()=>focusCount++}:null
            });
            const scan = vm.runInContext(`(${scanFunction})`,context);
            await scan("test-barcode");
            return {calls,focusCount,modalCount};
        }
        const cancelledVvp = await simulateScan({isVvp:true,capturedQuantity:null});
        assert.equal(cancelledVvp.calls.length,0,"VVP modal cancellation invokes no Stock Inward scan/mutation IPC");
        assert.equal(cancelledVvp.focusCount,1,"cancel restores scanner focus");
        const confirmedVvp = await simulateScan({isVvp:true,capturedQuantity:15});
        assert.equal(confirmedVvp.calls[0].quantity,15,"VVP confirmation sends entered additive quantity");
        const normalSku = await simulateScan({isVvp:false,capturedQuantity:15});
        assert.equal(normalSku.modalCount,0,"normal Product never opens quantity modal");
        assert.equal(normalSku.calls[0].quantity,1,"normal Product scan remains one unit");
        const schemaAuthority=fs.readFileSync(path.join(__dirname,"../src/database/schemaVersion.js"),"utf8");
        assert.ok(Number(schemaAuthority.match(/CURRENT_DB_SCHEMA_VERSION = (\d+)/)?.[1]) >= 25,"V16 adds guarded outward document deletion while preserving V14/V15 inward contracts");
        assert.match(schemaAuthority, /from:\s*24,\s*to:\s*25,\s*name:\s*"v2_1_stock_inward_incremental_receipts"/, "incremental receipt migration is registered in the forward schema chain");
        const billingUi=fs.readFileSync(path.join(__dirname,"../src/renderer/app.js"),"utf8");
        assert.match(billingUi,/blockedReason === "MRP_RECONCILIATION_REQUIRED"\)\s*\{\s*await showDynamicMrpReconciliationDrawer\(product, mrpOptions\)/,"Billing explains unallocated MRP stock in a KLBS drawer instead of a generic native alert");
        assert.match(billingUi,/MRP STOCK NEEDS A PHYSICAL CHECK[\s\S]*?unallocatedQuantity[\s\S]*?Stock Inward → Physical MRP Count[\s\S]*?This records the MRP split without adding or removing stock/,"Billing drawer explains the precise reason, safe next step and unchanged stock total");
        console.log("PASS V13/V5 preservation, V14 integrity, V16 outward-only deletion guard, persistent draft, repeated scanning, invoice reconciliation, unknown partial post, retry, idempotency, no Supplier liability, UI/authorization contracts.");
